package com.bank.salaryindex;

import java.util.*;
import java.util.logging.*;

public class MergeDemo {
    private static final Logger log = Logger.getLogger("SalaryIndex");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", 1000000.0),
            new Employee("Priya", 250000.0),
            new Employee("Amit", 400000.0),
            new Employee("Amit", 450000.0));   // duplicate name, higher salary
        SalaryIndexService service = new SalaryIndexService();

        Map<String, Double> index = service.nameToHighestSalary(staff);
        log.info(() -> "Amit → " + index.get("Amit") + " (higher of 400000/450000)");
        log.info(() -> "full index = " + index);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/SalaryIndexService.java ───
class SalaryIndexService {
    Map<String, Double> nameToHighestSalary(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toMap(
                Employee::getName,     // key: name (can repeat)
                Employee::getSalary,   // value: salary
                Double::max));         // merge: keep higher salary
    }
}
